<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Rect from './Rect.vue'
import {globalSearch} from './state'
import {api} from '../store'
import {heritageOverview,loadHeritage,type PublishedRecord} from './heritage-state'
interface CataloguePage {items:PublishedRecord[];matched:number;total_published:number;page:number;page_size:number}
const route=useRoute(),router=useRouter(),result=ref<CataloguePage|null>(null),problem=ref(''),loading=ref(true),impression=ref(false),institution=ref(''),period=ref(String(route.query.period||'')),page=ref(1)
const character=computed(()=>String(route.query.character||'')),unknownSlug=computed(()=>!!route.params.slug&&!String(route.params.slug).startsWith('node-'))
const rows=computed(()=>result.value?.items||[]),pages=computed(()=>Math.max(1,Math.ceil((result.value?.matched||0)/6)))
let version=0,timer:ReturnType<typeof setTimeout>|undefined
if(route.query.q)globalSearch.value=String(route.query.q)
else if(route.query.period||route.query.character)globalSearch.value=''
async function load(){const ticket=++version;loading.value=true;problem.value='';const query=new URLSearchParams({q:globalSearch.value.trim(),institution:institution.value,period:period.value,character:character.value,page:String(page.value),page_size:'6'});try{const data=await api<CataloguePage>('/heritage/catalogue?'+query);if(ticket===version)result.value=data}catch(e){if(ticket===version)problem.value=e instanceof Error?e.message:'馆藏记录读取失败'}finally{if(ticket===version)loading.value=false}}
watch([globalSearch,institution,period,character],()=>{loading.value=true;problem.value='';page.value=1;clearTimeout(timer);timer=setTimeout(load,180)},{immediate:true})
watch(page,load)
onMounted(loadHeritage)
onBeforeUnmount(()=>{version++;clearTimeout(timer)})
function reset(){globalSearch.value='';institution.value='';period.value='';if(character.value)void router.replace('/catalog')}
</script>
<template>
<Rect :x="194" :y="86" :w="1455" :h="833" plain>
 <section class="im-live-catalog">
  <header><div><small>OFFICIAL COLLECTION RECORDS</small><h1>有据可查的一方印</h1><p>从官方藏品记录读实物，从出处读历史。缺项和分期差异保留原状。</p></div><RouterLink to="/graph">进入古印知识宇宙 ↗</RouterLink></header>
  <p v-if="unknownSlug" class="live-catalog-notice">刚才的构图示例没有馆藏凭证，未列为真实文物。以下是已接入的官方藏品。</p>
  <p v-if="character" class="live-catalog-notice">只显示官方释文含「{{character}}」的馆藏记录。<RouterLink to="/catalog">查看全部</RouterLink></p>
  <div class="live-catalog-tools"><b>{{result?.matched??'—'}} / {{result?.total_published??'—'}} 条</b><label><span>来源</span><select v-model="institution" aria-label="馆藏机构筛选"><option value="">全部机构</option><option v-for="(_,name) in heritageOverview?.institutions" :key="name">{{name}}</option></select></label><label><span>时代</span><select v-model="period" aria-label="馆藏时代筛选"><option value="">全部时代分组</option><option v-for="(_,name) in heritageOverview?.by_period_group" :key="name">{{name}}</option></select></label><label class="live-search"><input v-model="globalSearch" placeholder="印文、文物号、制印人…" aria-label="搜索真实馆藏"></label><button :aria-pressed="impression" @click="impression=!impression">{{impression?'馆藏图像':'官方钤本'}}</button></div>
  <p v-if="problem" role="alert">{{problem}} <button @click="load">重试</button></p>
  <p v-if="loading" role="status" class="live-loading">正在核对馆藏记录…</p>
  <div v-if="!problem" class="live-catalog-grid" :aria-busy="loading"><article v-for="r in rows" :key="r.node_id"><RouterLink :to="'/graph?node='+r.node_id"><img v-if="impression?r.impression_available:r.preview_available" :src="impression?r.impression!.display_url:r.display_url" :alt="impression?r.impression!.caption:r.caption" loading="lazy" decoding="async"><span v-else class="live-missing-image">{{impression?'本条目未接入官方钤本':'暂无本地预览'}}<small>请核对官方原页</small></span></RouterLink><small>{{r.accession_number||'官方条目 '+r.catalogue_record_id+'（非文物号）'}} · {{r.museum}}</small><h2>{{r.official_title}}</h2><dl><dt>年代</dt><dd :class="{disputed:r.period_conflict}">{{r.period}}</dd><dt>材质</dt><dd>{{r.material}}</dd><dt>尺寸</dt><dd>{{r.dimensions}}</dd><template v-if="r.maker"><dt>制印人</dt><dd>{{r.maker}}（目录记载）</dd></template></dl><footer><RouterLink :to="'/graph?node='+r.node_id">读印与关联 ↗</RouterLink><a :href="r.page_url" target="_blank" rel="noopener noreferrer">官方原文 ↗</a></footer></article></div>
  <p v-if="!loading&&!problem&&!rows.length" class="live-catalog-notice">没有匹配的已接入馆藏。<button @click="reset">清除筛选</button></p>
  <nav v-if="!problem" class="live-pagination" aria-label="馆藏分页"><button :disabled="page<=1||loading" @click="page--">上一页</button><span>第 {{page}} / {{pages}} 页 · 每页6条</span><button :disabled="page>=pages||loading" @click="page++">下一页</button></nav>
  <p class="live-catalog-footnote">条目数不是馆藏总件数，组印按一条记录计。官方条目号不冒充文物号；目录分期和正文不同时标明待核对。原14条文献印稿仍在资料工作台，不视为实物。</p>
  <details class="live-bibliography"><summary>论著目录 · {{heritageOverview?.counts.bibliography_citations??'—'}} 条官方著录</summary><p>只核对目录，不代表取得或读过全文。作者、出版栏和时间按原目录保留。</p><ol><li v-for="b in heritageOverview?.bibliography" :key="b.id"><a :href="b.url" target="_blank" rel="noopener noreferrer">{{b.title}} ↗</a><span>{{b.author_as_listed||'目录未列作者'}} · {{b.publication_as_listed}} · {{b.date_as_listed}}</span><small>目录著录 · 全文未核读</small></li></ol></details>
 </section>
</Rect>
</template>
<style scoped>
