grid dl{display:grid;grid-template-columns:36px minmax(0,1fr);gap:4px 8px;font:10px/1.7 system-ui;margin:0;color:#cbb490}.live-catalog-grid dd{margin:0;overflow-wrap:anywhere}.live-catalog-grid dt{color:#ab8850}.live-catalog-grid footer{display:flex;justify-content:space-between;gap:12px;padding-top:10px;margin-top:10px;border-top:1px solid #473c29;font:11px system-ui}.im-live-catalog .live-catalog-footnote{padding-top:12px;font-size:10px;color:#b79765}.im-live-catalog .live-catalog-notice{padding:12px;margin:12px 0;border:1px solid #665b35;color:#d9c592}.live-pagination{display:flex;justify-content:center;align-items:center;gap:20px;margin-top:16px;font:11px system-ui}.im-live-catalog .live-loading{padding:10px;border:1px solid #645339;margin-bottom:12px}.disputed{color:#e6ba7a}.live-bibliography{border-top:1px solid #51442e;padding-top:16px;margin-top:17px;font:12px/1.8 system-ui}.live-bibliography summary{cursor:pointer;color:#dcc899}.live-bibliography ol{padding-left:20px}.live-bibliography li{margin:12px 0}.live-bibliography li>span,.live-bibliography li>small{display:block;color:#bda072;font-size:10px}
@media(max-width:999px){.im-live-catalog{height:auto;overflow:visible;padding:20px 16px}.im-live-catalog header{display:block}.im-live-catalog header>a{display:inline-block;margin-top:12px;font-size:12px}.im-live-catalog h1{font-size:26px}.live-catalog-tools{gap:10px;font-size:10px}.live-catalog-tools .live-search{margin:0;width:100%;order:-1}.live-catalog-tools input{flex:1;width:0;min-width:0}.live-catalog-tools select{width:116px;font-size:10px}.live-catalog-grid{grid-template-columns:1fr}.live-catalog-grid img,.live-missing-image{height:205px}.live-catalog-grid h2{font-size:19px}.live-catalog-grid dl{font-size:11px}.live-pagination{gap:13px}}
